function getPoolMemoryUsage(): string {
   const totalBytes = cropPool.reduce((acc, c) => acc + (c.pixels?.length || (c.width * c.height * 4)), 0);
   if (totalBytes === 0) return "0 MB";
   const mb = totalBytes / (1024 * 1024);
   if (mb < 0.1) {
      return `${Math.round(totalBytes / 1024)} KB`;
   }
   return `${mb.toFixed(1)} MB`;
}

