function ensureDirectories() {
   if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, { recursive: true });
   }
   if (!fs.existsSync(CROPS_DIR)) {
      fs.mkdirSync(CROPS_DIR, { recursive: true });
   }
}

function parseSafeNumber(
   val: any,
   fallback: number,
   min?: number,
   max?: number,
   integer: boolean = false
): number {
   if (val === undefined || val === null || val === "") return fallback;
   const num = typeof val === "number" ? val : parseFloat(String(val));
   if (isNaN(num) || !isFinite(num)) return fallback;
   let result = integer ? Math.round(num) : num;
   if (min !== undefined && result < min) result = min;
   if (max !== undefined && result > max) result = max;
   return result;
}

function parseSafeColor(val: any, fallback: string = "#FFFFFF"): string {
   if (typeof val !== "string") return fallback;
   const str = val.trim();
   if (/^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(str)) {
      return str.toUpperCase();
   }
   return fallback;
}

function hexToRgba(hex: string): { r: number; g: number; b: number; a: number } {
   let str = hex.replace("#", "").trim();
   if (str.length === 3) {
      str = str.split("").map((c) => c + c).join("") + "FF";
   } else if (str.length === 6) {
      str += "FF";
   } else if (str.length !== 8) {
      return { r: 255, g: 255, b: 255, a: 1.0 };
   }
   const num = parseInt(str, 16);
   if (isNaN(num)) return { r: 255, g: 255, b: 255, a: 1.0 };
   return {
      r: (num >>> 24) & 255,
      g: (num >>> 16) & 255,
      b: (num >>> 8) & 255,
      a: (num & 255) / 255.0,
   };
}

function loadSettings() {
   ensureDirectories();
   // Primary config is config.json; fallback to data/settings.json if migrating
   const targetFile = fs.existsSync(CONFIG_FILE)
      ? CONFIG_FILE
      : (fs.existsSync(SETTINGS_FILE) ? SETTINGS_FILE : null);

   if (targetFile) {
      try {
         const raw = fs.readFileSync(targetFile, "utf-8");
         // Strip single-line comments // ... to support JSON with comments
         const sanitized = raw.replace(/^\s*\/\/.*$/gm, "");
         const parsed = JSON.parse(sanitized);
         const loadedParts =
            Array.isArray(parsed.selectedBodyParts)
               ? parsed.selectedBodyParts
               : defaultSettings.selectedBodyParts;

         settings = {
            port: parseSafeNumber(parsed.port, defaultSettings.port, 1, 65535, true),
            hookTimeout: parseSafeNumber(parsed.hookTimeout, defaultSettings.hookTimeout, 500, 120000, true),
            selectedBodyParts: loadedParts,
            storageMode: parsed.storageMode === "DISK" ? "DISK" : "MEMORY",
            maxPoolSize: parseSafeNumber(parsed.maxPoolSize, defaultSettings.maxPoolSize, 10, 10000, true),
            minCropDimension: parseSafeNumber(parsed.minCropDimension, defaultSettings.minCropDimension, 0, 2048, true),
            maxCropDimension: parseSafeNumber(parsed.maxCropDimension, defaultSettings.maxCropDimension, 32, 4096, true),
            censorMapping:
               parsed.censorMapping && typeof parsed.censorMapping === "object"
                  ? parsed.censorMapping
                  : { ...DEFAULT_CENSOR_MAPPING },
            censorShape:
               parsed.censorShape === "CIRCLE" || parsed.censorShape === "ELLIPSE" || parsed.censorShape === "HEART"
                  ? parsed.censorShape
                  : "RECTANGLE",
            censorScale: (() => {
               const raw = parseSafeNumber(parsed.censorScale, defaultSettings.censorScale, 0.1, 500.0);
               return raw > 5.0 ? raw / 100.0 : raw;
            })(),
            censorRounding: parseSafeNumber(parsed.censorRounding, defaultSettings.censorRounding, 0, 500),
            censorFeathering: parseSafeNumber(parsed.censorFeathering, defaultSettings.censorFeathering, 0, 100),
            borderWidth: parseSafeNumber(parsed.borderWidth, defaultSettings.borderWidth, 0, 100),
            borderColor: parseSafeColor(parsed.borderColor, defaultSettings.borderColor),
            shadowSize: parseSafeNumber(parsed.shadowSize, defaultSettings.shadowSize, 0, 100),
            shadowColor: parseSafeColor(parsed.shadowColor, defaultSettings.shadowColor),
            shadowOffsetX: parseSafeNumber(parsed.shadowOffsetX, defaultSettings.shadowOffsetX, -100, 100),
            shadowOffsetY: parseSafeNumber(parsed.shadowOffsetY, defaultSettings.shadowOffsetY, -100, 100),
            shadowBlur: parseSafeNumber(parsed.shadowBlur, defaultSettings.shadowBlur, 0, 100),
            videoConsistency:
               parsed.videoConsistency === "PER_BODY_PART" || parsed.videoConsistency === "OFF"
                  ? parsed.videoConsistency
                  : "TRACKING",
         };
         console.log("[AutoCrop Plugin] Persistent settings loaded from", path.basename(targetFile), settings);
      } catch (err) {
         console.error("[AutoCrop Plugin] Error reading config:", err);
      }
   }
}

let isSavingLocally = false;
let isSavingLocallyTimer: NodeJS.Timeout | null = null;

function saveSettings() {
   try {
      isSavingLocally = true;
      if (isSavingLocallyTimer) clearTimeout(isSavingLocallyTimer);
      isSavingLocallyTimer = setTimeout(() => {
         isSavingLocally = false;
         isSavingLocallyTimer = null;
      }, 500);

      const commentHeader = [
         "// =============================================================================",
         "// AutoCrop Configuration & Censor Mapping",
         "//",
         "// Available Body Types for 'censorMapping' and 'selectedBodyParts':",
         "//   FEMALEBREASTEXPOSED, FEMALEBREASTCOVERED, NIPPLEEXPOSED, NIPPLECOVERED,",
         "//   TUMMYEXPOSED, TUMMYCOVERED, BUTTOCKSEXPOSED, BUTTOCKSCOVERED,",
         "//   FEMALEGENITALIAEXPOSED, FEMALEGENITALIACOVERED, MALEGENITALIAEXPOSED,",
         "//   MALEGENITALIACOVERED, MALEBREASTEXPOSED, MALEBREASTCOVERED,",
         "//   FACEFEMALE, FACEMALE, ANUSEXPOSED, ANUSCOVERED, HANDEXPOSED, HANDCOVERED,",
         "//   FEETEXPOSED, FEETCOVERED, ARMPITSEXPOSED, ARMPITSCOVERED, EYE, MOUTH, SILHOUETTE",
         "//",
         "// Censor Settings:",
         "//   censorShape: \"RECTANGLE\" | \"CIRCLE\" | \"ELLIPSE\" | \"HEART\"",
         "//   censorScale: 1.0 (multiplier, e.g. 0.7 = 70%)",
         "//   censorRounding: 0 (%)",
         "//   censorFeathering: 0 (%)",
         "//   borderWidth: 0 (px)",
         "//   borderColor: \"#FFFFFF\" (hex)",
         "//   videoConsistency: \"TRACKING\" | \"PER_BODY_PART\" | \"OFF\"",
         "//   hookTimeout: 10000 (ms timeout for frame/image processing)",
         "// =============================================================================",
         "",
      ].join("\n");

      const fileContent = commentHeader + JSON.stringify(settings, null, 2);
      fs.writeFileSync(CONFIG_FILE, fileContent, "utf-8");
      console.log("[AutoCrop Plugin] Persistent settings saved to config.json.");
   } catch (err) {
      console.error("[AutoCrop Plugin] Error saving config.json:", err);
   }
}

let saveSettingsTimer: NodeJS.Timeout | null = null;
function debouncedSaveSettings() {
   if (saveSettingsTimer) clearTimeout(saveSettingsTimer);
   saveSettingsTimer = setTimeout(() => {
      saveSettings();
      saveSettingsTimer = null;
   }, 300);
}

let configWatcher: fs.FSWatcher | null = null;
let configChangeDebounceTimer: NodeJS.Timeout | null = null;

function handleConfigFileChange() {
   if (isSavingLocally) return;

   if (configChangeDebounceTimer) clearTimeout(configChangeDebounceTimer);
   configChangeDebounceTimer = setTimeout(() => {
      configChangeDebounceTimer = null;
      if (isSavingLocally) return;

      console.log("[AutoCrop Plugin] config.json change detected on disk. Reloading settings live...");
      const prevStorageMode = settings.storageMode;

      loadSettings();

      // Trim pool if maxPoolSize was lowered
      while (cropPool.length > settings.maxPoolSize) {
         const oldest = cropPool.shift();
         if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
            try {
               fs.unlinkSync(oldest.filePath);
            } catch (e) {}
         }
      }

      // If switched to DISK or pool is empty in DISK mode, load crops
      if (settings.storageMode === "DISK" && (prevStorageMode !== "DISK" || cropPool.length === 0)) {
         loadCropsFromDisk();
      }

      broadcastConfiguration();
      console.log("[AutoCrop Plugin] Live reload complete. Current settings:", settings);
   }, 300);
}

function setupConfigWatcher() {
   try {
      if (configWatcher) {
         configWatcher.close();
         configWatcher = null;
      }
      if (!fs.existsSync(CONFIG_FILE)) {
         return;
      }
      configWatcher = fs.watch(CONFIG_FILE, (eventType) => {
         if (eventType === "rename") {
            // Re-bind watcher after atomic save rename
            setTimeout(() => {
               setupConfigWatcher();
               handleConfigFileChange();
            }, 100);
         } else {
            handleConfigFileChange();
         }
      });
      configWatcher.on("error", (err) => {
         console.warn("[AutoCrop Plugin] Config file watcher error:", err);
      });
      console.log("[AutoCrop Plugin] Live file watcher active for config.json.");
   } catch (err) {
      console.warn("[AutoCrop Plugin] Could not setup file watcher for config.json:", err);
   }
}

function getLabelFolderName(label?: number | string): string {
   if (label === undefined || label === null) return "UNCATEGORIZED";
   if (typeof label === "number") {
      return LABEL_NAMES[label] || `LABEL_${label}`;
   }
   return String(label).toUpperCase().replace(/[^A-Z0-9_-]/g, "_");
}

function saveCropToDisk(crop: Crop, label?: number | string): string | undefined {
   ensureDirectories();
   try {
      const folderName = getLabelFolderName(label);
      const targetDir = path.join(CROPS_DIR, folderName);
      if (!fs.existsSync(targetDir)) {
         fs.mkdirSync(targetDir, { recursive: true });
      }

      const fileName = `crop_${Date.now()}_${Math.random().toString(36).substring(2, 8)}_${crop.width}x${crop.height}.crop`;
      const filePath = path.join(targetDir, fileName);

      const header = Buffer.alloc(8);
      header.writeUInt32LE(crop.width, 0);
      header.writeUInt32LE(crop.height, 4);

      const fileBuffer = Buffer.concat([header, Buffer.from(crop.pixels)]);
      fs.writeFileSync(filePath, fileBuffer);
      return filePath;
   } catch (err) {
      console.error("[AutoCrop Plugin] Error saving crop file to disk:", err);
      return undefined;
   }
}

function getAllCropFiles(dir: string): string[] {
   let results: string[] = [];
   if (!fs.existsSync(dir)) return results;
   const entries = fs.readdirSync(dir, { withFileTypes: true });
   for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
         results = results.concat(getAllCropFiles(fullPath));
      } else if (entry.isFile() && entry.name.endsWith(".crop")) {
         results.push(fullPath);
      }
   }
   return results;
}

function loadCropsFromDisk() {
   ensureDirectories();
   if (settings.storageMode !== "DISK") return;

   cropPool = [];
   try {
      const cropFiles = getAllCropFiles(CROPS_DIR);
      console.log(`[AutoCrop Plugin] Loading persistent crops from ${CROPS_DIR} (${cropFiles.length} files found)...`);

      for (const filePath of cropFiles) {
         if (cropPool.length >= settings.maxPoolSize) break;
         const data = fs.readFileSync(filePath);
         if (data.length < 8) continue;

         const width = data.readUInt32LE(0);
         const height = data.readUInt32LE(4);
         const expectedPixelLen = width * height * 4;

         if (data.length >= 8 + expectedPixelLen) {
            const rawPixels = new Uint8Array(data.buffer, data.byteOffset + 8, expectedPixelLen);
            const category = path.basename(path.dirname(filePath)) || "UNCATEGORIZED";
            cropPool.push({
               id: path.basename(filePath),
               category,
               width,
               height,
               aspectRatio: width / height,
               pixels: new Uint8Array(rawPixels),
               filePath,
            });
         }
      }
      console.log(`[AutoCrop Plugin] Loaded ${cropPool.length} persistent crops into pool.`);
   } catch (err) {
      console.error("[AutoCrop Plugin] Error loading crops from disk:", err);
   }
}

function clearActiveCrops() {
   if (settings.storageMode === "DISK") {
      ensureDirectories();
      try {
         const cropFiles = getAllCropFiles(CROPS_DIR);
         for (const filePath of cropFiles) {
            try {
               fs.unlinkSync(filePath);
            } catch (e) {}
         }
         // Clean up empty directories
         const subDirs = fs.readdirSync(CROPS_DIR, { withFileTypes: true }).filter((d) => d.isDirectory());
         for (const sub of subDirs) {
            try {
               fs.rmSync(path.join(CROPS_DIR, sub.name), { recursive: true, force: true });
            } catch (e) {}
         }
         console.log(`[AutoCrop Plugin] Cleared ${cropFiles.length} persistent crop files from disk.`);
      } catch (err) {
         console.error("[AutoCrop Plugin] Error clearing disk crops:", err);
      }
   }
   cropPool = [];
   resetVideoTracking();
   console.log(`[AutoCrop Plugin] Cleared active crop pool.`);
}

function matchesSelectedBodyParts(label: number, targets: string[] | string): boolean {
   const targetArray = Array.isArray(targets) ? targets : [targets];
   if (targetArray.length === 0) {
      return false; // If no body parts are selected, do not crop anything
   }
   const labelName = LABEL_NAMES[label]?.toUpperCase() ?? "";
   return targetArray.some((target) => {
      const normalized = target.toUpperCase().trim();
      return (
         labelName === normalized ||
         label.toString() === normalized
      );
   });
}

function cropImageRegion(
   image: Uint8Array,
   imgW: number,
   imgH: number,
   startX: number,
   startY: number,
   boxW: number,
   boxH: number,
   maxDim: number,
   minDim: number = 0,
   category: string = "UNCATEGORIZED"
): Crop | null {
   if (boxW <= 0 || boxH <= 0) return null;
   if (minDim > 0 && (boxW < minDim || boxH < minDim)) return null;

   const rawPixels = new Uint8Array(boxW * boxH * 4);
   for (let py = 0; py < boxH; py++) {
      const srcY = startY + py;
      if (srcY < 0 || srcY >= imgH) continue;
      for (let px = 0; px < boxW; px++) {
         const srcX = startX + px;
         if (srcX < 0 || srcX >= imgW) continue;
         const srcIdx = (srcY * imgW + srcX) * 4;
         const dstIdx = (py * boxW + px) * 4;
         rawPixels[dstIdx + 0] = image[srcIdx + 0];
         rawPixels[dstIdx + 1] = image[srcIdx + 1];
         rawPixels[dstIdx + 2] = image[srcIdx + 2];
         rawPixels[dstIdx + 3] = image[srcIdx + 3];
      }
   }

   // Downscale crop if it exceeds maxCropDimension
   if (boxW <= maxDim && boxH <= maxDim) {
      return {
         id: `crop_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
         category,
         width: boxW,
         height: boxH,
         aspectRatio: boxW / boxH,
         pixels: rawPixels,
      };
   }

   const scale = Math.min(maxDim / boxW, maxDim / boxH);
   const dstW = Math.max(1, Math.floor(boxW * scale));
   const dstH = Math.max(1, Math.floor(boxH * scale));
   const dstPixels = new Uint8Array(dstW * dstH * 4);

   for (let py = 0; py < dstH; py++) {
      const srcY = Math.min(boxH - 1, Math.floor(py / scale));
      for (let px = 0; px < dstW; px++) {
         const srcX = Math.min(boxW - 1, Math.floor(px / scale));
         const srcIdx = (srcY * boxW + srcX) * 4;
         const dstIdx = (py * dstW + px) * 4;

         dstPixels[dstIdx + 0] = rawPixels[srcIdx + 0];
         dstPixels[dstIdx + 1] = rawPixels[srcIdx + 1];
         dstPixels[dstIdx + 2] = rawPixels[srcIdx + 2];
         dstPixels[dstIdx + 3] = rawPixels[srcIdx + 3];
      }
   }

   return {
      id: `crop_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      category,
      width: dstW,
      height: dstH,
      aspectRatio: dstW / dstH,
      pixels: dstPixels,
   };
}

function findBestCropCandidate(targetW: number, targetH: number, targetLabel?: number | string): Crop | null {
   if (cropPool.length === 0 || targetW <= 0 || targetH <= 0) return null;

   let candidatePool: Crop[] = cropPool;

   if (settings.censorMapping) {
      let allowedCategories: string[] | undefined;

      if (targetLabel !== undefined && targetLabel !== null) {
         const labelName = typeof targetLabel === "number" ? (LABEL_NAMES[targetLabel] || String(targetLabel)) : String(targetLabel);
         const normalizedLabel = labelName.toUpperCase().trim();
         allowedCategories = settings.censorMapping[normalizedLabel];
      }

      // If no specific mapping for this label, check DEFAULT
      if (allowedCategories === undefined) {
         allowedCategories = settings.censorMapping["DEFAULT"];
      }

      // If no mapping or DEFAULT is configured, do not censor
      if (allowedCategories === undefined) {
         return null;
      }

      // Filter out empty strings, whitespace, and "NONE"
      const cleanedAllowed = allowedCategories
         .map((c) => String(c).trim().toUpperCase())
         .filter((c) => c.length > 0 && c !== "NONE");

      // If mapping explicitly specified empty or no categories (e.g. [] or [""] or ["NONE"]), do not apply any crop!
      if (cleanedAllowed.length === 0) {
         return null;
      }

      // If not wildcard, filter candidate pool strictly
      if (!cleanedAllowed.includes("*") && !cleanedAllowed.includes("ALL")) {
         const matched = cropPool.filter((c) => cleanedAllowed.includes(c.category?.toUpperCase()?.trim()));
         if (matched.length === 0) {
            // Strictly do NOT fall back to general pool! If no matching crop exists, return null (nothing used).
            return null;
         }
         candidatePool = matched;
      }
   }

   const targetAspect = targetW / targetH;

   // Score crops by symmetric log aspect ratio distance
   const scored = candidatePool.map((crop) => {
      const diff = Math.abs(Math.log(crop.aspectRatio / targetAspect));
      return { crop, diff };
   });

   // Sort ascending by aspect ratio difference
   scored.sort((a, b) => a.diff - b.diff);

   // Select top K best aspect-matched candidates
   const count = Math.min(TOP_K_CANDIDATES, scored.length);
   const topCandidates = scored.slice(0, count);

   // Pick one randomly from top candidates
   const selected = topCandidates[Math.floor(Math.random() * topCandidates.length)];
   return selected.crop;
}

interface VideoTrack {
   id: number;
   crop: Crop;
   box: { x: number; y: number; w: number; h: number };
   label: number | string;
   lastSeenTime: number;
}

let trackedVideoCrops: VideoTrack[] = [];
let nextTrackId = 1;
let lastVideoFrameTimestamp = 0;
const pickedBodyPartCrops = new Map<string, { crop: Crop; lastSeenTime: number }>();

function normalizeLabelKey(label: any): string {
   if (label === undefined || label === null) return "";
   if (typeof label === "number") {
      return (LABEL_NAMES[label] || String(label)).toUpperCase().trim();
   }
   return String(label).toUpperCase().trim();
}

function calculateIoU(
   a: { x: number; y: number; w: number; h: number },
   b: { x: number; y: number; w: number; h: number }
): number {
   const xA = Math.max(a.x, b.x);
   const yA = Math.max(a.y, b.y);
   const xB = Math.min(a.x + a.w, b.x + b.w);
   const yB = Math.min(a.y + a.h, b.y + b.h);
   const interArea = Math.max(0, xB - xA) * Math.max(0, yB - yA);
   const aArea = a.w * a.h;
   const bArea = b.w * b.h;
   const unionArea = aArea + bArea - interArea;
   if (unionArea <= 0) return 0;
   return Math.min(1.0, Math.max(0, interArea / unionArea));
}

function calculateDistanceSq(
   a: { x: number; y: number; w: number; h: number },
   b: { x: number; y: number; w: number; h: number }
): number {
   const cAx = a.x + a.w / 2;
   const cAy = a.y + a.h / 2;
   const cBx = b.x + b.w / 2;
   const cBy = b.y + b.h / 2;
   const dx = cAx - cBx;
   const dy = cAy - cBy;
   return dx * dx + dy * dy;
}

function resetVideoTracking() {
   trackedVideoCrops = [];
   pickedBodyPartCrops.clear();
}

function invertBoxRegion(
   targetImage: Uint8Array,
   imgW: number,
   imgH: number,
   startX: number,
   startY: number,
   boxW: number,
   boxH: number
) {
   for (let py = 0; py < boxH; py++) {
      const dstY = startY + py;
      if (dstY < 0 || dstY >= imgH) continue;
      for (let px = 0; px < boxW; px++) {
         const dstX = startX + px;
         if (dstX < 0 || dstX >= imgW) continue;
         const idx = (dstY * imgW + dstX) * 4;
         targetImage[idx + 0] = 255 - targetImage[idx + 0];
         targetImage[idx + 1] = 255 - targetImage[idx + 1];
         targetImage[idx + 2] = 255 - targetImage[idx + 2];
      }
   }
}

// Canonical PuryFi SVG Heart path:
// "M12,24l-1.7-1.7C4.1,16.2,0,12.1,0,7.2C0,3.2,2.9,0,6.6,0c2.1,0,4.1,1.1,5.4,2.7C13.3,1.1,15.3,0,17.4,0C21.1,0,24,3.2,24,7.2c0,4.9-4.1,9-10.3,15.1L12,24z"
function evalCubicBezier(
   p0x: number, p0y: number,
   p1x: number, p1y: number,
   p2x: number, p2y: number,
   p3x: number, p3y: number,
   t: number
): { x: number; y: number } {
   const mt = 1 - t;
   return {
      x: mt * mt * mt * p0x + 3 * mt * mt * t * p1x + 3 * mt * t * t * p2x + t * t * t * p3x,
      y: mt * mt * mt * p0y + 3 * mt * mt * t * p1y + 3 * mt * t * t * p2y + t * t * t * p3y,
   };
}

function initCanonicalHeart(): { left: { x: number; y: number }[]; full: { x: number; y: number }[] } {
   const left: { x: number; y: number }[] = [];
   left.push({ x: 12, y: 24 });
   left.push({ x: 10.3, y: 22.3 });

   const c1 = [10.3, 22.3, 4.1, 16.2, 0, 12.1, 0, 7.2];
   const c2 = [0, 7.2, 0, 3.2, 2.9, 0, 6.6, 0];
   const c3 = [6.6, 0, 8.7, 0, 10.7, 1.1, 12, 2.7];

   const N = 16;
   for (let i = 1; i <= N; i++) left.push(evalCubicBezier(c1[0], c1[1], c1[2], c1[3], c1[4], c1[5], c1[6], c1[7], i / N));
   for (let i = 1; i <= N; i++) left.push(evalCubicBezier(c2[0], c2[1], c2[2], c2[3], c2[4], c2[5], c2[6], c2[7], i / N));
   for (let i = 1; i <= N; i++) left.push(evalCubicBezier(c3[0], c3[1], c3[2], c3[3], c3[4], c3[5], c3[6], c3[7], i / N));

   const full: { x: number; y: number }[] = [...left];
   for (let i = left.length - 2; i >= 1; i--) {
      full.push({ x: 24 - left[i].x, y: left[i].y });
   }

   return { left, full };
}

const CANONICAL_HEART = initCanonicalHeart();

interface CachedHeartGeometry {
   boxW: number;
   boxH: number;
   halfW: number;
   segCount: number;
   segData: Float32Array; // [x1, y1, dx, dy, l2, minY, maxY]
   spans: Float32Array[];
}

let cachedHeartGeometry: CachedHeartGeometry | null = null;

function getCachedHeartGeometry(boxW: number, boxH: number): CachedHeartGeometry {
   if (cachedHeartGeometry && cachedHeartGeometry.boxW === boxW && cachedHeartGeometry.boxH === boxH) {
      return cachedHeartGeometry;
   }

   const scaleX = boxW / 24;
   const scaleY = boxH / 24;
   const left = CANONICAL_HEART.left;
   const segCount = left.length - 1;
   const segData = new Float32Array(segCount * 7);

   for (let i = 0; i < segCount; i++) {
      const x1 = left[i].x * scaleX;
      const y1 = left[i].y * scaleY;
      const x2 = left[i + 1].x * scaleX;
      const y2 = left[i + 1].y * scaleY;
      const dx = x2 - x1;
      const dy = y2 - y1;
      const l2 = dx * dx + dy * dy;
      const minY = Math.min(y1, y2);
      const maxY = Math.max(y1, y2);
      const o = i * 7;
      segData[o] = x1;
      segData[o + 1] = y1;
      segData[o + 2] = dx;
      segData[o + 3] = dy;
      segData[o + 4] = l2;
      segData[o + 5] = minY;
      segData[o + 6] = maxY;
   }

   const full = CANONICAL_HEART.full;
   const fullCount = full.length;
   const scaledPolyX = new Float32Array(fullCount);
   const scaledPolyY = new Float32Array(fullCount);
   for (let i = 0; i < fullCount; i++) {
      scaledPolyX[i] = full[i].x * scaleX;
      scaledPolyY[i] = full[i].y * scaleY;
   }

   const rowCount = Math.max(1, Math.ceil(boxH));
   const spans: Float32Array[] = new Array(rowCount);
   const tempXs: number[] = [];

   for (let y = 0; y < rowCount; y++) {
      const py = y + 0.5;
      tempXs.length = 0;
      for (let i = 0, j = fullCount - 1; i < fullCount; j = i++) {
         const y1 = scaledPolyY[j];
         const y2 = scaledPolyY[i];
         if ((y1 > py) !== (y2 > py)) {
            const x1 = scaledPolyX[j];
            const x2 = scaledPolyX[i];
            const xInt = x1 + ((py - y1) * (x2 - x1)) / (y2 - y1);
            tempXs.push(xInt);
         }
      }
      tempXs.sort((a, b) => a - b);
      spans[y] = new Float32Array(tempXs);
   }

   cachedHeartGeometry = {
      boxW,
      boxH,
      halfW: boxW / 2,
      segCount,
      segData,
      spans,
   };

   return cachedHeartGeometry;
}

function getHeartSignedDistance(relX: number, relY: number, boxW: number, boxH: number): number {
   const geom = getCachedHeartGeometry(boxW, boxH);
   const intY = Math.floor(relY);

   let inside = false;
   if (intY >= 0 && intY < geom.spans.length && relX >= 0 && relX <= boxW) {
      const rowSpans = geom.spans[intY];
      for (let k = 0; k < rowSpans.length; k += 2) {
         if (relX >= rowSpans[k] && relX <= rowSpans[k + 1]) {
            inside = true;
            break;
         }
      }
   }

   const xFold = relX > geom.halfW ? boxW - relX : relX;
   let minDistSq = 1e9;
   const segData = geom.segData;
   const segCount = geom.segCount;

   for (let i = 0; i < segCount; i++) {
      const o = i * 7;
      const minY = segData[o + 5];
      const maxY = segData[o + 6];
      const dyMin = relY < minY ? minY - relY : relY > maxY ? relY - maxY : 0;
      if (dyMin * dyMin >= minDistSq) continue;

      const x1 = segData[o];
      const y1 = segData[o + 1];
      const dx = segData[o + 2];
      const dy = segData[o + 3];
      const l2 = segData[o + 4];

      let t = ((xFold - x1) * dx + (relY - y1) * dy) / l2;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      const qx = x1 + t * dx;
      const qy = y1 + t * dy;
      const dSq = (xFold - qx) * (xFold - qx) + (relY - qy) * (relY - qy);
      if (dSq < minDistSq) minDistSq = dSq;
   }

   return inside ? Math.sqrt(minDistSq) : -Math.sqrt(minDistSq);
}

function computeShapeDistance(
   px: number,
   py: number,
   baseX: number,
   baseY: number,
   boxW: number,
   boxH: number,
   shape: "RECTANGLE" | "CIRCLE" | "ELLIPSE" | "HEART",
   roundingPx: number
): number {
   if (!Number.isFinite(boxW) || !Number.isFinite(boxH) || boxW <= 0 || boxH <= 0) {
      return 1.0;
   }
   if (!Number.isFinite(px) || !Number.isFinite(py)) {
      return 1.0;
   }

   const relX = px - baseX;
   const relY = py - baseY;

   let signedDist = 0; // positive = inside, negative = outside

   if (shape === "CIRCLE") {
      const cx = boxW / 2;
      const cy = boxH / 2;
      // In PuryFi: radius = max(w, h) / 2 to cover the box
      const r = Math.max(boxW, boxH) / 2;
      const dist = Math.hypot(relX - cx, relY - cy);
      signedDist = r - dist;
   } else if (shape === "ELLIPSE") {
      const cx = boxW / 2;
      const cy = boxH / 2;
      const rx = boxW / 2;
      const ry = boxH / 2;
      if (rx <= 0 || ry <= 0) return 0;
      const normDist = Math.hypot((relX - cx) / rx, (relY - cy) / ry);
      signedDist = (1.0 - normDist) * Math.min(rx, ry);
   } else if (shape === "HEART") {
      if (boxW !== boxH) {
         const size = (boxW + boxH) / 2;
         const offX = (boxW - size) / 2;
         const offY = (boxH - size) / 2;
         signedDist = getHeartSignedDistance(relX - offX, relY - offY, size, size);
      } else {
         signedDist = getHeartSignedDistance(relX, relY, boxW, boxH);
      }
   } else {
      // RECTANGLE (with corner rounding in pixels)
      const maxR = Math.min(boxW / 2, boxH / 2);
      const R = Math.max(0, Math.min(roundingPx, maxR));
      const halfW = boxW / 2;
      const halfH = boxH / 2;
      const dx = Math.abs(relX - halfW) - (halfW - R);
      const dy = Math.abs(relY - halfH) - (halfH - R);
      const outsideDist = Math.hypot(Math.max(0, dx), Math.max(0, dy));
      const insideDist = Math.min(0, Math.max(dx, dy));
      signedDist = -(outsideDist + insideDist - R);
   }

   return signedDist;
}

function computeHermiteFade(dist: number, featheringPx: number): number {
   if (featheringPx <= 0) {
      // 1px subpixel antialiasing edge centered on 0
      if (dist >= 0.5) return 1.0;
      if (dist <= -0.5) return 0.0;
      return dist + 0.5;
   }
   // Skia Normal Blur hermite approximation matching PuryFi:
   // Symmetrical blur centered on shape contour (dist = 0 -> alpha = 0.5)
   // dist = -featheringPx -> alpha = 0.0
   // dist = +featheringPx -> alpha = 1.0
   const t = Math.max(0, Math.min(1, (dist + featheringPx) / (2 * featheringPx)));
   return t * t * (3 - 2 * t);
}

function computeShapeAlpha(
   px: number,
   py: number,
   baseX: number,
   baseY: number,
   boxW: number,
   boxH: number,
   shape: "RECTANGLE" | "CIRCLE" | "ELLIPSE" | "HEART",
   roundingPx: number,
   featheringPx: number
): number {
   const signedDist = computeShapeDistance(px, py, baseX, baseY, boxW, boxH, shape, roundingPx);
   return computeHermiteFade(signedDist, featheringPx);
}

function blitCropAspectPreserved(
   targetImage: Uint8Array,
   imgW: number,
   imgH: number,
   startX: number,
   startY: number,
   endX: number,
   endY: number,
   baseX: number,
   baseY: number,
   baseW: number,
   baseH: number,
   crop: Crop,
   shape: "RECTANGLE" | "CIRCLE" | "ELLIPSE" | "HEART" = "RECTANGLE",
   roundingPx = 0,
   featheringPx = 0,
   borderWidthPx = 0,
   borderColorRgba = { r: 255, g: 255, b: 255, a: 1.0 },
   shadowSizePx = 0,
   shadowColorRgba = { r: 0, g: 0, b: 0, a: 0.5 },
   shadowOffsetX = 0,
   shadowOffsetY = 0,
   shadowBlurPx = 0
) {
   const srcW = crop.width;
   const srcH = crop.height;
   if (
      !Number.isFinite(baseW) ||
      !Number.isFinite(baseH) ||
      baseW <= 0 ||
      baseH <= 0 ||
      srcW <= 0 ||
      srcH <= 0
   ) {
      return;
   }

   const scale = Math.max(baseW / srcW, baseH / srcH);
   const srcCoverW = baseW / scale;
   const srcCoverH = baseH / scale;
   const srcStartX = (srcW - srcCoverW) / 2;
   const srcStartY = (srcH - srcCoverH) / 2;

   const hasBorder = borderWidthPx > 0;
   const hasShadow = (shadowSizePx > 0 || shadowOffsetX !== 0 || shadowOffsetY !== 0 || shadowBlurPx > 0) && shadowColorRgba.a > 0;
   const totalShadowBlur = shadowBlurPx + featheringPx;

   for (let dstY = startY; dstY < endY; dstY++) {
      if (dstY < 0 || dstY >= imgH) continue;
      const relY = dstY - baseY;
      const srcY = Math.max(0, Math.min(srcH - 1, Math.floor(srcStartY + relY / scale)));

      for (let dstX = startX; dstX < endX; dstX++) {
         if (dstX < 0 || dstX >= imgW) continue;
         const relX = dstX - baseX;

         // Foreground shape distance
         const signedDist = computeShapeDistance(dstX, dstY, baseX, baseY, baseW, baseH, shape, roundingPx);

         let aOuter = 0;
         let wCrop = 0;
         let wBorder = 0;

         if (!hasBorder) {
            aOuter = computeHermiteFade(signedDist, featheringPx);
            wCrop = aOuter;
         } else {
            // Outer edge aligns with box boundary (exact 1x border thickness)
            aOuter = computeHermiteFade(signedDist, featheringPx);
            // Inner edge is inset into the box by borderWidthPx
            const aInner = computeHermiteFade(signedDist - borderWidthPx, featheringPx);
            wCrop = Math.min(1.0, Math.max(0.0, aInner));
            const rawBorderWeight = Math.max(0.0, aOuter - aInner);
            wBorder = rawBorderWeight * borderColorRgba.a;
         }

         // Shadow computation behind the shape
         let shadowAlpha = 0;
         if (hasShadow) {
            const shadowBaseDist = computeShapeDistance(
               dstX - shadowOffsetX,
               dstY - shadowOffsetY,
               baseX,
               baseY,
               baseW,
               baseH,
               shape,
               roundingPx
            );
            const shadowDist = shadowBaseDist + shadowSizePx;
            shadowAlpha = computeHermiteFade(shadowDist, totalShadowBlur) * shadowColorRgba.a;
         }

         if (aOuter <= 0 && shadowAlpha <= 0) continue;

         const fgAlpha = Math.min(1.0, wCrop + wBorder);
         const remainingBg = Math.max(0.0, 1.0 - fgAlpha);
         const wShadow = hasShadow ? Math.max(0.0, shadowAlpha * remainingBg) : 0.0;
         const wBg = Math.max(0.0, remainingBg - wShadow);

         const dstIdx = (dstY * imgW + dstX) * 4;

         if (wCrop >= 1.0) {
            const srcX = Math.max(0, Math.min(srcW - 1, Math.floor(srcStartX + relX / scale)));
            const srcIdx = (srcY * srcW + srcX) * 4;
            targetImage[dstIdx + 0] = crop.pixels[srcIdx + 0];
            targetImage[dstIdx + 1] = crop.pixels[srcIdx + 1];
            targetImage[dstIdx + 2] = crop.pixels[srcIdx + 2];
            targetImage[dstIdx + 3] = crop.pixels[srcIdx + 3];
         } else {
            let cropR = 0, cropG = 0, cropB = 0;
            if (wCrop > 0) {
               const srcX = Math.max(0, Math.min(srcW - 1, Math.floor(srcStartX + relX / scale)));
               const srcIdx = (srcY * srcW + srcX) * 4;
               cropR = crop.pixels[srcIdx + 0];
               cropG = crop.pixels[srcIdx + 1];
               cropB = crop.pixels[srcIdx + 2];
            }

            targetImage[dstIdx + 0] = Math.round(
               targetImage[dstIdx + 0] * wBg +
               shadowColorRgba.r * wShadow +
               borderColorRgba.r * wBorder +
               cropR * wCrop
            );
            targetImage[dstIdx + 1] = Math.round(
               targetImage[dstIdx + 1] * wBg +
               shadowColorRgba.g * wShadow +
               borderColorRgba.g * wBorder +
               cropG * wCrop
            );
            targetImage[dstIdx + 2] = Math.round(
               targetImage[dstIdx + 2] * wBg +
               shadowColorRgba.b * wShadow +
               borderColorRgba.b * wBorder +
               cropB * wCrop
            );
            targetImage[dstIdx + 3] = 255;
         }
      }
   }
}

