async function broadcastConfiguration() {
   const config = buildConfiguration();
   for (const conn of activeConnections) {
      try {
         await conn.sendMessage("setPluginConfiguration", { configuration: config });
      } catch (err) {
         console.error("[AutoCrop Plugin] Error broadcasting configuration:", err);
      }
   }
}

console.log(`[AutoCrop Plugin] Starting WebSocket server on port ${PORT}... (ws://localhost:${PORT})`);

const server = new SDK.WebSocketServer(PORT);

server.on("connection", (connection) => {
   console.log("[AutoCrop Plugin] PuryFi extension connected!");

   connection.once("close", () => {
      activeConnections.delete(connection);
   });
   connection.on("error", () => {
      activeConnections.delete(connection);
   });

   connection.once("open", async () => {
      activeConnections.add(connection);
      // 1. Handle Handshake
      await new Promise<void>((resolve) => {
         connection.once("message", "ready", (payload) => {
            const res = connection.handleReadyMessage(payload);
            if (res.type === "ok") {
               resolve();
            }
            return res;
         });
      });

      console.log("[AutoCrop Plugin] Handshake successful.");

      const manifest: SDK.PluginManifest = {
         name: "AutoCrop",
         version: "2.7.0",
         description: "AutoCrop automatically collects cropped parts of images and introduces its own censor mode where collected crops are applied as censorship.",
         author: "0131",
         website: null,
         censorModes: [
            {
               id: "autocrop",
               name: "AutoCrop",
               tooltip: "AutoCrop",
               supportsVideo: true,
               supportsMixedMode: true,
               icon: "data:image/png;base64,",
},
         ],
      };

      await connection.sendMessage("setPluginManifest", { manifest });
      await connection.sendMessage("setPluginConfiguration", { configuration: buildConfiguration() });

      // Handle Configuration Changes from PuryFi Extension UI
      connection.on("message", "configurationChange", async (payload) => {
         let poolChanged = false;
         let settingsChanged = false;

         if (payload.configuration?.targetBodyParts) {
            const val = payload.configuration.targetBodyParts.value;
            if (Array.isArray(val)) {
               settings.selectedBodyParts = val.map(String);
               settingsChanged = true;
            }
         }

         if (payload.configuration?.storageMode) {
            const oldMode = settings.storageMode;
            const newMode = String(payload.configuration.storageMode.value) === "DISK" ? "DISK" : "MEMORY";
            if (oldMode !== newMode) {
               settings.storageMode = newMode;
               settingsChanged = true;
               if (newMode === "DISK") {
                  loadCropsFromDisk();
                  poolChanged = true;
               }
            }
         }

         if (payload.configuration?.maxPoolSize) {
            const val = parseSafeNumber(payload.configuration.maxPoolSize.value, settings.maxPoolSize, 10, 10000, true);
            if (val !== settings.maxPoolSize) {
               settings.maxPoolSize = val;
               settingsChanged = true;
               const prevLen = cropPool.length;
               while (cropPool.length > settings.maxPoolSize) {
                  const oldest = cropPool.shift();
                  if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
                     try {
                        fs.unlinkSync(oldest.filePath);
                     } catch (e) {}
                  }
               }
               if (cropPool.length !== prevLen) {
                  poolChanged = true;
               }
            }
         }

         if (payload.configuration?.hookTimeout) {
            const val = parseSafeNumber(payload.configuration.hookTimeout.value, settings.hookTimeout, 500, 120000, true);
            if (val !== settings.hookTimeout) {
               settings.hookTimeout = val;
               settingsChanged = true;
               for (const conn of activeConnections) {
                  conn.sendMessage("subscribeToMediaCensorHooks", {
                     stage: "before",
                     onlyIfObjectsDetected: true,
                     timeout: settings.hookTimeout,
                     targets: ["image", "video"],
                     onlyWhenModeActive: {
                        image: false,
                        video: true,
                     },
                  }).catch(() => {});
               }
            }
         }

         if (payload.configuration?.minCropDimension) {
            const val = parseSafeNumber(payload.configuration.minCropDimension.value, settings.minCropDimension, 0, 2048, true);
            if (val !== settings.minCropDimension) {
               settings.minCropDimension = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.maxCropDimension) {
            const val = parseSafeNumber(payload.configuration.maxCropDimension.value, settings.maxCropDimension, 64, 4096, true);
            if (val !== settings.maxCropDimension) {
               settings.maxCropDimension = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.censorShape) {
            const val = String(payload.configuration.censorShape.value).toUpperCase();
            if (val === "RECTANGLE" || val === "CIRCLE" || val === "ELLIPSE" || val === "HEART") {
               if (val !== settings.censorShape) {
                  settings.censorShape = val as any;
                  settingsChanged = true;
               }
            }
         }

         if (payload.configuration?.censorRounding) {
            const val = parseSafeNumber(payload.configuration.censorRounding.value, settings.censorRounding, 0, 500);
            if (val !== settings.censorRounding) {
               settings.censorRounding = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.censorScale) {
            const rawVal = payload.configuration.censorScale.value;
            const parsedNum = parseSafeNumber(rawVal, Math.round(settings.censorScale * 100), 10, 500);
            const val = parseSafeNumber(parsedNum / 100.0, settings.censorScale, 0.1, 5.0);
            if (val !== settings.censorScale) {
               settings.censorScale = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.censorFeathering) {
            const val = parseSafeNumber(payload.configuration.censorFeathering.value, settings.censorFeathering, 0, 100);
            if (val !== settings.censorFeathering) {
               settings.censorFeathering = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.borderWidth) {
            const val = parseSafeNumber(payload.configuration.borderWidth.value, settings.borderWidth, 0, 100);
            if (val !== settings.borderWidth) {
               settings.borderWidth = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.borderColor) {
            const val = parseSafeColor(payload.configuration.borderColor.value, settings.borderColor);
            if (val !== settings.borderColor) {
               settings.borderColor = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.shadowSize) {
            const val = parseSafeNumber(payload.configuration.shadowSize.value, settings.shadowSize, 0, 100);
            if (val !== settings.shadowSize) {
               settings.shadowSize = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.shadowColor) {
            const val = parseSafeColor(payload.configuration.shadowColor.value, settings.shadowColor);
            if (val !== settings.shadowColor) {
               settings.shadowColor = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.shadowOffsetX) {
            const val = parseSafeNumber(payload.configuration.shadowOffsetX.value, settings.shadowOffsetX, -100, 100);
            if (val !== settings.shadowOffsetX) {
               settings.shadowOffsetX = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.shadowOffsetY) {
            const val = parseSafeNumber(payload.configuration.shadowOffsetY.value, settings.shadowOffsetY, -100, 100);
            if (val !== settings.shadowOffsetY) {
               settings.shadowOffsetY = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.shadowBlur) {
            const val = parseSafeNumber(payload.configuration.shadowBlur.value, settings.shadowBlur, 0, 100);
            if (val !== settings.shadowBlur) {
               settings.shadowBlur = val;
               settingsChanged = true;
            }
         }

         if (payload.configuration?.videoConsistency) {
            const val = String(payload.configuration.videoConsistency.value).toUpperCase();
            if (val === "TRACKING" || val === "PER_BODY_PART" || val === "OFF") {
               if (val !== settings.videoConsistency) {
                  settings.videoConsistency = val as any;
                  resetVideoTracking();
                  settingsChanged = true;
               }
            }
         }

         if (payload.configuration?.clearCropsAction?.value === true) {
            clearActiveCrops();
            poolChanged = true;
            settingsChanged = true;
         }

         if (poolChanged) {
            saveSettings();
            await broadcastConfiguration();
         } else if (settingsChanged) {
            debouncedSaveSettings();
         }
      });

      // Handle Settings Export Hook from PuryFi
      connection.on("message", "exportPluginSettings", async () => {
         console.log("[AutoCrop Plugin] Exporting settings on request from PuryFi");
         return {
            settings: {
               storageMode: settings.storageMode,
               maxPoolSize: settings.maxPoolSize,
               hookTimeout: settings.hookTimeout,
               minCropDimension: settings.minCropDimension,
               maxCropDimension: settings.maxCropDimension,
               censorShape: settings.censorShape,
               censorRounding: settings.censorRounding,
               censorScale: settings.censorScale,
               censorFeathering: settings.censorFeathering,
               borderWidth: settings.borderWidth,
               borderColor: settings.borderColor,
               shadowSize: settings.shadowSize,
               shadowColor: settings.shadowColor,
               shadowOffsetX: settings.shadowOffsetX,
               shadowOffsetY: settings.shadowOffsetY,
               shadowBlur: settings.shadowBlur,
               videoConsistency: settings.videoConsistency,
               selectedBodyParts: settings.selectedBodyParts,
               censorMapping: settings.censorMapping,
            },
         };
      });

      // Handle Settings Import Hook from PuryFi
      connection.on("message", "importPluginSettings", async (payload: any) => {
         console.log("[AutoCrop Plugin] Received imported settings from PuryFi:", payload?.settings);
         if (!payload || !payload.settings || typeof payload.settings !== "object") {
            return { type: "error", message: "Invalid settings payload" };
         }
         const imported = payload.settings;
         let poolChanged = false;
         let settingsChanged = false;

         if (imported.storageMode && (imported.storageMode === "DISK" || imported.storageMode === "MEMORY")) {
            if (settings.storageMode !== imported.storageMode) {
               settings.storageMode = imported.storageMode;
               settingsChanged = true;
               if (imported.storageMode === "DISK") {
                  loadCropsFromDisk();
                  poolChanged = true;
               }
            }
         }
         if (typeof imported.maxPoolSize === "number") {
            const val = parseSafeNumber(imported.maxPoolSize, settings.maxPoolSize, 10, 10000, true);
            if (val !== settings.maxPoolSize) {
               settings.maxPoolSize = val;
               settingsChanged = true;
               const prevLen = cropPool.length;
               while (cropPool.length > settings.maxPoolSize) {
                  const oldest = cropPool.shift();
                  if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
                     try {
                        fs.unlinkSync(oldest.filePath);
                     } catch (e) {}
                  }
               }
               if (cropPool.length !== prevLen) poolChanged = true;
            }
         }
         if (typeof imported.hookTimeout === "number") {
            const val = parseSafeNumber(imported.hookTimeout, settings.hookTimeout, 500, 120000, true);
            if (val !== settings.hookTimeout) {
               settings.hookTimeout = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.minCropDimension === "number") {
            const val = parseSafeNumber(imported.minCropDimension, settings.minCropDimension, 0, 2048, true);
            if (val !== settings.minCropDimension) {
               settings.minCropDimension = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.maxCropDimension === "number") {
            const val = parseSafeNumber(imported.maxCropDimension, settings.maxCropDimension, 64, 4096, true);
            if (val !== settings.maxCropDimension) {
               settings.maxCropDimension = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.censorShape === "string") {
            const val = imported.censorShape.toUpperCase();
            if (val !== settings.censorShape) {
               settings.censorShape = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.censorRounding === "number") {
            const val = parseSafeNumber(imported.censorRounding, settings.censorRounding, 0, 500);
            if (val !== settings.censorRounding) {
               settings.censorRounding = val;
               settingsChanged = true;
            }
         }
         if (imported.censorScale !== undefined) {
            const rawVal = imported.censorScale;
            const parsedNum = parseSafeNumber(rawVal, Math.round(settings.censorScale * 100), 10, 500);
            const val = parseSafeNumber(parsedNum > 10 ? parsedNum / 100.0 : parsedNum, settings.censorScale, 0.1, 5.0);
            if (val !== settings.censorScale) {
               settings.censorScale = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.censorFeathering === "number") {
            const val = parseSafeNumber(imported.censorFeathering, settings.censorFeathering, 0, 100);
            if (val !== settings.censorFeathering) {
               settings.censorFeathering = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.borderWidth === "number") {
            const val = parseSafeNumber(imported.borderWidth, settings.borderWidth, 0, 100);
            if (val !== settings.borderWidth) {
               settings.borderWidth = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.borderColor === "string") {
            const val = parseSafeColor(imported.borderColor, settings.borderColor);
            if (val !== settings.borderColor) {
               settings.borderColor = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.shadowSize === "number") {
            const val = parseSafeNumber(imported.shadowSize, settings.shadowSize, 0, 100);
            if (val !== settings.shadowSize) {
               settings.shadowSize = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.shadowColor === "string") {
            const val = parseSafeColor(imported.shadowColor, settings.shadowColor);
            if (val !== settings.shadowColor) {
               settings.shadowColor = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.shadowOffsetX === "number") {
            const val = parseSafeNumber(imported.shadowOffsetX, settings.shadowOffsetX, -100, 100);
            if (val !== settings.shadowOffsetX) {
               settings.shadowOffsetX = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.shadowOffsetY === "number") {
            const val = parseSafeNumber(imported.shadowOffsetY, settings.shadowOffsetY, -100, 100);
            if (val !== settings.shadowOffsetY) {
               settings.shadowOffsetY = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.shadowBlur === "number") {
            const val = parseSafeNumber(imported.shadowBlur, settings.shadowBlur, 0, 100);
            if (val !== settings.shadowBlur) {
               settings.shadowBlur = val;
               settingsChanged = true;
            }
         }
         if (typeof imported.videoConsistency === "string") {
            const val = imported.videoConsistency.toUpperCase();
            if (val !== settings.videoConsistency) {
               settings.videoConsistency = val;
               settingsChanged = true;
            }
         }
         if (Array.isArray(imported.selectedBodyParts)) {
            settings.selectedBodyParts = imported.selectedBodyParts.map(String);
            settingsChanged = true;
         } else if (Array.isArray(imported.targetBodyParts)) {
            settings.selectedBodyParts = imported.targetBodyParts.map(String);
            settingsChanged = true;
         }
         if (imported.censorMapping && typeof imported.censorMapping === "object") {
            settings.censorMapping = imported.censorMapping;
            settingsChanged = true;
         }

         if (settingsChanged) {
            saveSettings();
         }
         await broadcastConfiguration();
         return { type: "ok" };
      });

      // 3. Request Intents and Subscribe to Pre-Censor Hook
      const requiredIntents: SDK.PluginIntent[] = [
         "requestMediaCensorHooks",
         "readMediaProcesses",
         "requestMediaProcesses",
      ];

      let isSubscribed = false;
      const subscribeAllHooks = async () => {
         if (isSubscribed) return;
         const subRes = await connection.sendMessage("subscribeToMediaCensorHooks", {
            stage: "before",
            onlyIfObjectsDetected: true,
            timeout: settings.hookTimeout,
            targets: ["image", "video"],
            onlyWhenModeActive: {
               image: false,
               video: true,
            },
         });
         console.log(`[AutoCrop Plugin] Subscribed to before-censor hook (timeout: ${settings.hookTimeout}ms):`, subRes);
         if (subRes.type === "ok") {
            isSubscribed = true;
         }
      };

      connection.on("message", "intentsGrant", async (payload) => {
         const granted = payload.intents || [];
         console.log("[AutoCrop Plugin] Intents granted event received:", granted);
         if (requiredIntents.every((intent) => granted.includes(intent))) {
            await subscribeAllHooks();
         }
      });

      console.log("[AutoCrop Plugin] Checking plugin intents...");
      const getRes = await connection.sendMessage("getPluginIntents", {});
      const grantedIntents = getRes.type === "ok" ? getRes.intents : [];
      console.log("[AutoCrop Plugin] Currently granted intents:", grantedIntents);

      if (requiredIntents.every((intent) => grantedIntents.includes(intent))) {
         await subscribeAllHooks();
      } else {
         console.log("[AutoCrop Plugin] Requesting missing intents from extension...");
         await connection.sendMessage("requestPluginIntents", {
            intents: requiredIntents,
         });
      }

      // 4. Handle Hook Requests
      connection.on("message", "mediaCensorHookRequest", (payload) => {
         const { stage, image, objects, width, height, url, isVideo: rawIsVideo, metadata } = payload as any;
         
         // Detect if this is a video frame
         const isVideo = Boolean(
            rawIsVideo ||
            metadata?.isVideo ||
            (typeof url === "string" && (
               url.includes("video") ||
               url.includes(".mp4") ||
               url.includes(".m3u8") ||
               url.startsWith("blob:")
            ))
         );

         console.log("\n=================== [AutoCrop Hook Request] ===================");
         console.log(`[DEBUG] Stage: "${stage}", Dimensions: ${width}x${height}, isVideo: ${isVideo}, URL: "${url || 'none'}"`);
         console.log(`[DEBUG] Censor Objects passed (count: ${objects?.length ?? 0}):`, objects);
         console.log(`[DEBUG] Metadata passed:`, metadata);
         console.log(`[DEBUG] Current Active Plugin Filters:`, settings.selectedBodyParts);

         const harvestObjects = metadata?.rawObjects || objects || [];
         console.log(`[DEBUG] Harvest Candidates total count: ${harvestObjects.length}`);

         if (stage === "before") {
            const modifiedImage = new Uint8Array(image.slice());
            let newCropsHarvested = 0;

            // Step A: HARVEST CROPS into cropPool (filtered by plugin's selectedBodyParts, disabled on video frames or when minCropDimension <= 0)
            if (!isVideo && settings.minCropDimension > 0 && settings.selectedBodyParts.length > 0 && harvestObjects.length > 0) {
               console.log(`[DEBUG Step A] Checking ${harvestObjects.length} objects against filters (minCropDimension: ${settings.minCropDimension}px)...`);
               for (const obj of harvestObjects) {
                  const labelStr = LABEL_NAMES[obj.label] || `LABEL_${obj.label}`;
                  const isMatch = matchesSelectedBodyParts(obj.label, settings.selectedBodyParts);
                  console.log(`   -> Object Label #${obj.label} ("${labelStr}"), Score: ${obj.score}, Rect: [x:${obj.rect?.x}, y:${obj.rect?.y}, w:${obj.rect?.width}, h:${obj.rect?.height}] => MATCH: ${isMatch}`);

                  if (isMatch) {
                     const r = obj.rect;
                     const isFraction = r.x <= 1.0 && r.y <= 1.0 && r.width <= 1.0 && r.height <= 1.0;

                     const pxX = isFraction ? r.x * width : r.x;
                     const pxY = isFraction ? r.y * height : r.y;
                     const pxW = isFraction ? r.width * width : r.width;
                     const pxH = isFraction ? r.height * height : r.height;

                     const startX = Math.max(0, Math.floor(pxX));
                     const startY = Math.max(0, Math.floor(pxY));
                     const boxW = Math.min(width - startX, Math.ceil(pxW));
                     const boxH = Math.min(height - startY, Math.ceil(pxH));

                     if (boxW < settings.minCropDimension || boxH < settings.minCropDimension) {
                        console.log(`      [Crop Skipped] Dimensions [${boxW}x${boxH}] are smaller than minCropDimension (${settings.minCropDimension}px)`);
                        continue;
                     }

                     console.log(`      [Crop Region] Computed Box: [startX: ${startX}, startY: ${startY}, w: ${boxW}, h: ${boxH}]`);

                     const crop = cropImageRegion(image, width, height, startX, startY, boxW, boxH, settings.maxCropDimension, settings.minCropDimension, labelStr);
                     if (crop && crop.pixels.length > 0) {
                        if (settings.storageMode === "DISK") {
                           crop.filePath = saveCropToDisk(crop, obj.label);
                           console.log(`      [Disk Save] Saved to file: ${crop.filePath}`);
                        }

                        console.log(`      [Harvest SUCCESS] Added crop to pool! Current pool size: ${cropPool.length + 1}`);
                        cropPool.push(crop);
                        newCropsHarvested++;

                        // Trim pool if size exceeds capacity
                        while (cropPool.length > settings.maxPoolSize) {
                           const oldest = cropPool.shift();
                           if (oldest?.filePath && fs.existsSync(oldest.filePath)) {
                              try {
                                 fs.unlinkSync(oldest.filePath);
                              } catch (e) {}
                           }
                        }
                     } else {
                        console.warn(`      [Crop WARNING] cropImageRegion returned null or empty pixels!`);
                     }
                  }
               }

               if (newCropsHarvested > 0) {
                  connection.sendMessage("setPluginConfiguration", { configuration: buildConfiguration() }).catch(() => {});
               }
            } else if (settings.selectedBodyParts.length === 0) {
               console.log(`[DEBUG Step A] Skipping crop harvesting because no body parts are selected.`);
            } else if (settings.minCropDimension <= 0) {
               console.log(`[DEBUG Step A] Skipping crop harvesting because Minimum Crop Pixel Dimension is set to 0 (collecting disabled).`);
            } else if (isVideo) {
               console.log(`[DEBUG Step A] Skipping harvest because frame was detected as video.`);
            } else {
               console.log(`[DEBUG Step A] No harvest objects available.`);
            }

            // Step B: CENSOR ALL ACTIVE BOXES passed by PuryFirefox extension!
            const isAutoCropActive =
               metadata?.censorName === "autocrop" ||
               metadata?.censorName === "mixed" ||
               metadata?.targetPluginId === "autocrop";
            console.log(`[DEBUG Step B] Active censorName: "${metadata?.censorName}", isAutoCropActive: ${isAutoCropActive}`);

            if (!isAutoCropActive) {
               console.log(`[DEBUG Step B] AutoCrop mode not active (active: ${metadata?.censorName}). Skipping image replacement, letting PuryFi handle internal censoring.`);
               console.log("===============================================================\n");
               return { type: "pass" };
            }

            let censoredCount = 0;
            const censorObjects = objects || [];
            const censorCfg = metadata?.censorConfig;
            const rawScale = settings.censorScale !== 1.0
               ? settings.censorScale
               : ((censorCfg?.presets?.[0]?.config?.scale) ?? settings.censorScale ?? 1.0);
            let parsedScale = parseSafeNumber(rawScale, 1.0, 0.1, 500.0);
            if (parsedScale > 5.0) {
               parsedScale = parsedScale / 100.0; // Entered as percentage like 70% or 100%
            }
            const censorScale = Math.max(0.1, Math.min(5.0, parsedScale));

            const effectiveShape = settings.censorShape || "RECTANGLE";
            const effectiveRounding = parseSafeNumber(settings.censorRounding, 0, 0, 100);
            const effectiveFeathering = parseSafeNumber(settings.censorFeathering, 0, 0, 100);
            const effectiveBorderWidth = parseSafeNumber(settings.borderWidth, 0, 0, 100);
            const effectiveBorderColor = parseSafeColor(settings.borderColor, "#FFFFFF");
            const effectiveShadowSize = parseSafeNumber(settings.shadowSize, 0, 0, 100);
            const effectiveShadowColor = parseSafeColor(settings.shadowColor, "#00000080");
            const effectiveShadowOffsetX = parseSafeNumber(settings.shadowOffsetX, 0, -100, 100);
            const effectiveShadowOffsetY = parseSafeNumber(settings.shadowOffsetY, 0, -100, 100);
            const effectiveShadowBlur = parseSafeNumber(settings.shadowBlur, 0, 0, 100);

            // In PuryFi: scale_factor = ((imgW + imgH) / 2.0) / 1024.0
            const imgSize = (width + height) / 2.0;
            const puryfiScaleFactor = imgSize / 1024.0;
            const pixelRounding = effectiveRounding * puryfiScaleFactor;
            const pixelFeathering = effectiveFeathering * puryfiScaleFactor;
            const pixelBorderW = effectiveBorderWidth > 0
               ? Math.max(1.0, Math.round(effectiveBorderWidth * puryfiScaleFactor))
               : 0;
            const borderColorRgba = hexToRgba(effectiveBorderColor);

            const pixelShadowSize = effectiveShadowSize * puryfiScaleFactor;
            const pixelShadowOffsetX = effectiveShadowOffsetX * puryfiScaleFactor;
            const pixelShadowOffsetY = effectiveShadowOffsetY * puryfiScaleFactor;
            const pixelShadowBlur = effectiveShadowBlur * puryfiScaleFactor;
            const shadowColorRgba = hexToRgba(effectiveShadowColor);
            const hasShadow = (pixelShadowSize > 0 || pixelShadowOffsetX !== 0 || pixelShadowOffsetY !== 0 || pixelShadowBlur > 0) && shadowColorRgba.a > 0;

            console.log(`[DEBUG Step B] Censoring ${censorObjects.length} active extension boxes (scale: ${censorScale}x, shape: ${effectiveShape}, rounding: ${effectiveRounding}%, feathering: ${effectiveFeathering}%, border: ${effectiveBorderWidth}px, shadow: ${effectiveShadowSize}px, blur: ${effectiveShadowBlur}px)...`);

            const now = Date.now();

            if (isVideo) {
               // Reset tracks if video was paused/idle for > 2500ms
               if (now - lastVideoFrameTimestamp > 2500) {
                  resetVideoTracking();
               }
               lastVideoFrameTimestamp = now;

               // Prune tracks older than 1500ms
               trackedVideoCrops = trackedVideoCrops.filter((t) => now - t.lastSeenTime <= 1500);
               for (const [key, entry] of pickedBodyPartCrops.entries()) {
                  if (now - entry.lastSeenTime > 2500) {
                     pickedBodyPartCrops.delete(key);
                  }
               }
            }

            const usedTrackIds = new Set<number>();

            for (const obj of censorObjects) {
               const r = obj?.rect;
               if (
                  !r ||
                  typeof r.x !== "number" ||
                  typeof r.y !== "number" ||
                  typeof r.width !== "number" ||
                  typeof r.height !== "number" ||
                  !Number.isFinite(r.x) ||
                  !Number.isFinite(r.y) ||
                  !Number.isFinite(r.width) ||
                  !Number.isFinite(r.height) ||
                  r.width <= 0 ||
                  r.height <= 0
               ) {
                  continue;
               }

               const isFraction = r.x <= 1.0 && r.y <= 1.0 && r.width <= 1.0 && r.height <= 1.0;

               const rawX = isFraction ? r.x * width : r.x;
               const rawY = isFraction ? r.y * height : r.y;
               const rawW = isFraction ? r.width * width : r.width;
               const rawH = isFraction ? r.height * height : r.height;

               if (rawW <= 0 || rawH <= 0 || !Number.isFinite(rawX) || !Number.isFinite(rawY)) {
                  continue;
               }

               // Apply censor mode scale factor (expanding from box center)
               const centerX = rawX + rawW / 2;
               const centerY = rawY + rawH / 2;

               let baseW = rawW;
               let baseH = rawH;

               if (effectiveShape === "CIRCLE" || effectiveShape === "HEART") {
                  // In PuryFi (shape.rs line 796): Circle and Heart shapes have 1:1 aspect ratio and are never squished/stretched
                  const rwh = (rawW + rawH) / 2;
                  baseW = rwh;
                  baseH = rwh;
               }

               const scaledW = baseW * censorScale;
               const scaledH = baseH * censorScale;

               const pxX = centerX - scaledW / 2;
               const pxY = centerY - scaledH / 2;

               // Expand blit bounding box by feathering pad, border, and shadow
               const padFeatherAndBorder = Math.ceil(pixelFeathering);
               let padLeft = padFeatherAndBorder;
               let padRight = padFeatherAndBorder;
               let padTop = padFeatherAndBorder;
               let padBottom = padFeatherAndBorder;

               if (hasShadow) {
                  const shadowSpread = Math.ceil(pixelShadowSize + pixelShadowBlur);
                  padLeft = Math.max(padLeft, Math.ceil(-pixelShadowOffsetX + shadowSpread));
                  padRight = Math.max(padRight, Math.ceil(pixelShadowOffsetX + shadowSpread));
                  padTop = Math.max(padTop, Math.ceil(-pixelShadowOffsetY + shadowSpread));
                  padBottom = Math.max(padBottom, Math.ceil(pixelShadowOffsetY + shadowSpread));
               }

               const startX = Math.max(0, Math.floor(pxX - padLeft));
               const startY = Math.max(0, Math.floor(pxY - padTop));
               const endX = Math.min(width, Math.ceil(pxX + scaledW + padRight));
               const endY = Math.min(height, Math.ceil(pxY + scaledH + padBottom));

               // Find best aspect-ratio matched candidate from pool (with video stabilization if video)
               let chosenCrop: Crop | null = null;

               if (isVideo && settings.videoConsistency !== "OFF") {
                  const labelKey = normalizeLabelKey(obj.label);

                  if (settings.videoConsistency === "PER_BODY_PART") {
                     const cached = pickedBodyPartCrops.get(labelKey);
                     if (cached) {
                        chosenCrop = cached.crop;
                        cached.lastSeenTime = now;
                     } else {
                        chosenCrop = findBestCropCandidate(scaledW, scaledH, obj.label);
                        if (chosenCrop) {
                           pickedBodyPartCrops.set(labelKey, { crop: chosenCrop, lastSeenTime: now });
                        }
                     }
                  } else {
                     // TRACKING (default): spatial IoU & centroid distance matching per detection
                     const normBox = {
                        x: pxX / width,
                        y: pxY / height,
                        w: scaledW / width,
                        h: scaledH / height,
                     };

                     let bestTrack: VideoTrack | null = null;
                     let bestScore = -1;

                     for (const track of trackedVideoCrops) {
                        if (usedTrackIds.has(track.id)) continue;
                        if (normalizeLabelKey(track.label) !== labelKey) continue;

                        const iou = calculateIoU(normBox, track.box);
                        const distSq = calculateDistanceSq(normBox, track.box);

                        let score = -1;
                        if (iou > 0.1) {
                           score = 1.0 + iou;
                        } else if (distSq < 0.09) {
                           score = 1.0 - Math.sqrt(distSq);
                        }

                        if (score > bestScore) {
                           bestScore = score;
                           bestTrack = track;
                        }
                     }

                     if (bestTrack) {
                        usedTrackIds.add(bestTrack.id);
                        chosenCrop = bestTrack.crop;
                        bestTrack.box = normBox;
                        bestTrack.lastSeenTime = now;
                     } else {
                        chosenCrop = findBestCropCandidate(scaledW, scaledH, obj.label);
                        if (chosenCrop) {
                           const newTrack: VideoTrack = {
                              id: nextTrackId++,
                              crop: chosenCrop,
                              box: normBox,
                              label: obj.label,
                              lastSeenTime: now,
                           };
                           trackedVideoCrops.push(newTrack);
                           usedTrackIds.add(newTrack.id);
                        }
                     }
                  }
               } else {
                  chosenCrop = findBestCropCandidate(scaledW, scaledH, obj.label);
               }

               if (chosenCrop) {
                  blitCropAspectPreserved(
                     modifiedImage,
                     width,
                     height,
                     startX,
                     startY,
                     endX,
                     endY,
                     pxX,
                     pxY,
                     scaledW,
                     scaledH,
                     chosenCrop,
                     effectiveShape,
                     pixelRounding,
                     pixelFeathering,
                     pixelBorderW,
                     borderColorRgba,
                     pixelShadowSize,
                     shadowColorRgba,
                     pixelShadowOffsetX,
                     pixelShadowOffsetY,
                     pixelShadowBlur
                  );
                  censoredCount++;
               } else {
                  console.log(`[DEBUG Step B] No matching crop available or allowed for box [${Math.floor(pxX)}, ${Math.floor(pxY)}, ${Math.floor(scaledW)}, ${Math.floor(scaledH)}] (label: ${obj.label}). Leaving region untouched.`);
               }
            }

            console.log(`[DEBUG Step B] Finished processing ${censorObjects.length} boxes (${censoredCount} censored with crops). Returning ok with skipInternalCensoring: true.`);
            console.log("===============================================================\n");
            return {
               type: "ok",
               image: modifiedImage,
               skipInternalCensoring: true,
            };
         }

         return { type: "pass" };
      });
   });
});

server.on("error", (err) => {
   console.error("[AutoCrop Plugin] Server error:", err);
});
